parameters.jsonBody:
={
  "model": "gemma2:2b",
  "prompt": "You are a professional Customer Service AI assistant. Analyze the incoming customer message and classify its intent. Respond ONLY with a valid JSON object with the following fields: 'intent' (string, e.g. order_status, refund, return, general_inquiry), 'confidence' (float between 0 and 1), 'requires_human' (boolean), and 'response' (friendly customer-facing reply). Message: '" + $json.customer_message + "'",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
const rawResponse = $input.first().json.response;
let parsed = {};
try {
  parsed = JSON.parse(rawResponse);
} catch (e) {
  parsed = {
    error: 'Failed to parse JSON',
    raw: rawResponse
  };
}
return [{ json: parsed }];
